-- ===== db/lab/bulk-data.sql =====

-- FoodDash lab data for Class 5: about ten months of orders, enough for query plans and indexes to matter.
-- Adds 52 restaurants, 20,000 customers, 300 riders, 300,000 orders and their items to a FoodDash
-- database that already has the schema and the demo data (Flyway V1 and V2).
-- Every value comes from a formula on a row number, so every laptop gets exactly the same data.
-- Takes about a minute. Run it once; to start again, load fooddash-lab.sql (it recreates the tables).

-- Row numbers 1 to 300,000.
DROP TABLE IF EXISTS lab_seq, lab_word, lab_dish, lab_restaurant, lab_customer, lab_rider, lab_menu;
CREATE TABLE lab_seq (n INT NOT NULL PRIMARY KEY);
INSERT INTO lab_seq (n)
SELECT a.d + 10 * b.d + 100 * c.d + 1000 * e.d + 10000 * f.d + 100000 * g.d + 1
FROM (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
      UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a
CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
      UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b
CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
      UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c
CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
      UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) e
CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
      UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) f
CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2) g;

-- Word lists: areas, restaurant kinds, first names and last names.
CREATE TABLE lab_word (list VARCHAR(10) NOT NULL, k INT NOT NULL, word VARCHAR(40) NOT NULL, PRIMARY KEY (list, k));
