-- 52 more restaurants: every area and kind not already taken by a demo restaurant; every seventh is closed.
INSERT INTO restaurant (public_id, name, area, is_open, created_at)
SELECT LOWER(CONCAT(LPAD(HEX(t.n), 8, '0'), '-0000-4000-8000-0000000000d1')), t.name, t.area, t.n MOD 7 <> 0,
       TIMESTAMP '2026-01-01 03:00:00'
FROM (
  SELECT ROW_NUMBER() OVER (ORDER BY k.k, a.k) AS n, CONCAT(a.word, ' ', k.word) AS name, a.word AS area
  FROM lab_word a CROSS JOIN lab_word k
  WHERE a.list = 'area' AND k.list = 'kind'
    AND CONCAT(a.word, ' ', k.word) NOT IN (SELECT name FROM restaurant)
) t
WHERE t.n <= 52;

INSERT INTO menu_item (public_id, restaurant_id, name, price, available)
SELECT LOWER(CONCAT(LPAD(HEX(r.id), 8, '0'), '-', LPAD(d.k, 4, '0'), '-4000-8000-0000000000e1')), r.id, d.name, d.price, TRUE
FROM restaurant r
JOIN lab_word k ON k.list = 'kind' AND r.name LIKE CONCAT('% ', k.word)
JOIN lab_dish d ON d.kind = k.k
WHERE r.public_id LIKE '%-0000-4000-8000-0000000000d1';

-- 20,000 more customers and 300 more riders.
INSERT INTO customer (public_id, name, phone, email, created_at)
SELECT LOWER(CONCAT(LPAD(HEX(s.n), 8, '0'), '-0000-4000-8000-0000000000c1')),
       CONCAT(f.word, ' ', l.word), CONCAT('+88015', LPAD(s.n, 8, '0')),
       CONCAT(LOWER(f.word), '.', s.n, '@example.com'),
       TIMESTAMP '2026-01-01 00:00:00' + INTERVAL s.n * 13 MINUTE
FROM lab_seq s
JOIN lab_word f ON f.list = 'first' AND f.k = s.n MOD 20
JOIN lab_word l ON l.list = 'last' AND l.k = (s.n DIV 20) MOD 20
WHERE s.n <= 20000;

INSERT INTO rider (public_id, name, phone, created_at)
SELECT LOWER(CONCAT(LPAD(HEX(s.n), 8, '0'), '-0000-4000-8000-0000000000a1')),
       CONCAT(f.word, ' ', l.word), CONCAT('+88019', LPAD(s.n, 8, '0')),
       TIMESTAMP '2026-01-02 00:00:00' + INTERVAL s.n HOUR
FROM lab_seq s
JOIN lab_word f ON f.list = 'first' AND f.k = s.n MOD 20
JOIN lab_word l ON l.list = 'last' AND l.k = (s.n DIV 20) MOD 20
WHERE s.n <= 300;

-- Numbered lists of restaurants, customers, riders and each restaurant's dishes, so the formulas
-- below never depend on the generated ids.
CREATE TABLE lab_restaurant (k INT NOT NULL PRIMARY KEY, id BIGINT NOT NULL, area VARCHAR(50) NOT NULL);
INSERT INTO lab_restaurant SELECT ROW_NUMBER() OVER (ORDER BY id) - 1, id, area FROM restaurant;
CREATE TABLE lab_customer (k INT NOT NULL PRIMARY KEY, id BIGINT NOT NULL, phone VARCHAR(16) NOT NULL);
INSERT INTO lab_customer SELECT ROW_NUMBER() OVER (ORDER BY id) - 1, id, phone FROM customer;
CREATE TABLE lab_rider (k INT NOT NULL PRIMARY KEY, id BIGINT NOT NULL);
INSERT INTO lab_rider SELECT ROW_NUMBER() OVER (ORDER BY id) - 1, id FROM rider;
CREATE TABLE lab_menu (restaurant_id BIGINT NOT NULL, k INT NOT NULL, menu_item_id BIGINT NOT NULL,
                       price DECIMAL(10,2) NOT NULL, dishes INT NOT NULL, PRIMARY KEY (restaurant_id, k));
INSERT INTO lab_menu
SELECT restaurant_id, ROW_NUMBER() OVER (PARTITION BY restaurant_id ORDER BY id) - 1, id, price,
       COUNT(*) OVER (PARTITION BY restaurant_id)
FROM menu_item;

-- 300,000 orders from 1 January to the end of October, mostly at lunch and dinner time.
-- Every fifth order goes to Dhanmondi Kacchi House, the busiest restaurant; some customers and riders are
-- far busier than others; the newest orders are still open.
INSERT INTO orders (public_id, customer_id, restaurant_id, rider_id, status, subtotal, delivery_fee, total,
                    delivery_line1, delivery_area, delivery_phone, created_at)
SELECT LOWER(CONCAT(LPAD(HEX(o.n), 8, '0'), '-0000-4000-8000-0000000000f1')), c.id, r.id,
       CASE WHEN o.status IN ('DELIVERED', 'PICKED_UP') THEN d.id END,
       o.status, 0, o.fee, o.fee,
       CONCAT('House ', o.n MOD 90 + 1, ', Road ', o.n MOD 27 + 1), r.area, c.phone, o.created_at
FROM (
  SELECT s.n,
         CASE WHEN s.n MOD 5 = 0 THEN 0 ELSE 1 + (s.n * 7919) MOD 59 END AS restaurant_k,
         ((((s.n * 104729) MOD 20011) * ((s.n * 104729) MOD 20011)) DIV 20011 + (s.n * 104729) MOD 20011) DIV 2
           MOD 20002 AS customer_k,
         ((((s.n * 31) MOD 302) * ((s.n * 31) MOD 302)) DIV 302 + (s.n * 31) MOD 302) DIV 2 AS rider_k,
         CASE WHEN s.n > 299880 THEN ELT(s.n MOD 4 + 1, 'PLACED', 'PAID', 'PAID', 'PICKED_UP')
              WHEN s.n MOD 80 IN (3, 40) THEN 'CANCELLED'
              ELSE 'DELIVERED' END AS status,
         CASE WHEN s.n MOD 3 = 0 THEN 60.00 ELSE 40.00 END AS fee,
         TIMESTAMP '2026-01-01 00:00:00'
           + INTERVAL (s.n - 1) * 304 DIV 300000 DAY
           + INTERVAL ELT(s.n MOD 10 + 1, 12, 13, 13, 14, 19, 20, 20, 21, 16, 11) - 6 HOUR
           + INTERVAL (s.n * 7) MOD 3600 SECOND AS created_at
  FROM lab_seq s
) o
JOIN lab_restaurant r ON r.k = o.restaurant_k
JOIN lab_customer c ON c.k = o.customer_k
JOIN lab_rider d ON d.k = o.rider_k
ORDER BY o.n;

-- One to three lines per order, different dishes from the restaurant's own menu; some dishes sell more.
INSERT INTO order_item (order_id, menu_item_id, quantity, unit_price)
SELECT o.id, m.menu_item_id, 1 + (CONV(SUBSTRING(o.public_id, 1, 8), 16, 10) + l.k) MOD 3 DIV 2, m.price
FROM orders o
JOIN (SELECT 0 AS k UNION ALL SELECT 1 UNION ALL SELECT 2) l
JOIN lab_menu m ON m.restaurant_id = o.restaurant_id
WHERE o.public_id LIKE '%-0000-4000-8000-0000000000f1'
  AND l.k <= CONV(SUBSTRING(o.public_id, 1, 8), 16, 10) MOD 3
  AND l.k < m.dishes
  AND m.k = (CASE WHEN CONV(SUBSTRING(o.public_id, 1, 8), 16, 10) MOD 15 < 5 THEN 0
                  WHEN CONV(SUBSTRING(o.public_id, 1, 8), 16, 10) MOD 15 < 9 THEN 1
                  WHEN CONV(SUBSTRING(o.public_id, 1, 8), 16, 10) MOD 15 < 12 THEN 2
                  WHEN CONV(SUBSTRING(o.public_id, 1, 8), 16, 10) MOD 15 < 14 THEN 3
                  ELSE 4 END + l.k) MOD m.dishes;

-- Totals from the lines (the schema checks total = subtotal + delivery_fee).
UPDATE orders o
JOIN (SELECT order_id, SUM(quantity * unit_price) AS subtotal FROM order_item GROUP BY order_id) t
  ON t.order_id = o.id
SET o.subtotal = t.subtotal, o.total = t.subtotal + o.delivery_fee
WHERE o.public_id LIKE '%-0000-4000-8000-0000000000f1';

DROP TABLE lab_seq, lab_word, lab_dish, lab_restaurant, lab_customer, lab_rider, lab_menu;
ANALYZE TABLE customer, restaurant, menu_item, rider, orders, order_item;

SELECT (SELECT COUNT(*) FROM restaurant) AS restaurants, (SELECT COUNT(*) FROM customer) AS customers,
       (SELECT COUNT(*) FROM rider) AS riders, (SELECT COUNT(*) FROM orders) AS orders,
       (SELECT COUNT(*) FROM order_item) AS order_items;
